<script setup lang="ts">
import DocumentList from '@/components/hr/DocumentList.vue'
import { useHrDepartment } from '@/composables/useHrDepartments'
import { returnToQuery, safeReturnTo } from '@/utils/safeReturnTo'
const route = useRoute(); const { t } = useI18n(); const { can } = useAccess(); const id = computed(() => Number(route.params.departmentId)); const isDetail = computed(() => route.path === `/hr/departments/${id.value}`); const query = useHrDepartment(computed(() => isDetail.value ? id.value : null)); const department = computed(() => query.data.value); const returnTo = computed(() => safeReturnTo(route.query.returnTo, '/hr/departments', ['/hr']))
</script>
<template><div v-if="isDetail" class="space-y-6"><SharedPageHeader :title="department?.name || t('hr.depts.title')" :back-to="returnTo"><NuxtLink v-if="department && can('hr.departments.manage')" :to="{ path: `/hr/departments/${id}/edit`, query: returnToQuery(route.fullPath) }"><Button>{{ t('hr.depts.edit') }}</Button></NuxtLink></SharedPageHeader><SharedPageState :loading="query.isLoading.value" :error="query.error.value" :empty="!department" @retry="query.refetch"><p class="text-sm text-muted-foreground">{{ department?.employee_count }} {{ t('hr.depts.employeeReason', { count: department?.employee_count }) }}</p><DocumentList v-if="can('hr.documents.read')" :department-id="id" :can-write="can('hr.documents.manage')" /></SharedPageState></div><NuxtPage v-else /></template>
